gtk-theme-name=adw-gtk3-dark","removes":"[Settings]","removesTruncated":false}}
{"user":"How to see accent color in the gtk inspector"}
{"user":"I think the names I used as define colors are not being used by GTK4 inside its GTK4-widget-factory because I can get the correct accent colors in the css inspect by its not showing on the slides nd buttons, can you help me check."}
{"Bash":"pkg-config --modversion libadwaita-1 2>/dev/null && gsettings get org.gnome.desktop.interface accent-color 2>/dev/null && gsettings get org.gnome.desktop.interface color-scheme 2>/dev/null"}
{"Bash":"pkg-config --modversion libadwaita-1 2>/dev/null && gsettings get org.gnome.desktop.interface accent-color 2>/dev/null && gsettings get org.gnome.desktop.interface color-scheme 2>/dev/null"}
{"Bash":"dpkg -l libadwaita-1-0 2>/dev/null | tail -1; gsettings get org.gnome.desktop.interface accent-color 2>/dev/null || echo "no accent-color key"; gsettings get org.gnome.desktop.interface color-scheme 2>/dev/null || echo "no color-scheme key""}
{"Bash":"find /usr/share/gtk-4.0 /usr/share/gnome-shell /usr/lib -name "*.css" 2>/dev/null | head -5; dpkg -L libadwaita-1-0 | grep '\.css'"}
{"Bash":"dpkg -L libadwaita-1-0 2>/dev/null | grep -E '\.(css|gresource)'"}
{"Bash":"find /usr/lib -name "libadwaita*.so*" 2>/dev/null | head -3"}
{"Bash":"gresource list /usr/lib/x86_64-linux-gnu/libadwaita-1.so.0 2>/dev/null | grep -i css | head -20"}
{"Bash":"gresource extract /usr/lib/x86_64-linux-gnu/libadwaita-1.so.0 /org/gnome/Adwaita/styles/defaults-dark.css 2>/dev/null | grep -i accent"}
{"Bash":"gresource list /usr/lib/x86_64-linux-gnu/libadwaita-1.so.0 2>/dev/null | grep -v 'yaru\|hc' | grep css"}
{"Bash":"gresource extract /usr/lib/x86_64-linux-gnu/libadwaita-1.so.0 /org/gnome/Adwaita/styles/base.css 2>/dev/null | grep -A3 -B1 'accent_bg_color\|accent_color' | head -60"}
{"Bash":"gresource extract /usr/lib/x86_64-linux-gnu/libadwaita-1.so.0 /org/gnome/Adwaita/styles/base.css 2>/dev/null | grep -E 'scale|slider|button\.suggested|switch:checked|checkbutton|progressbar' | grep -i 'accent\|background' | head -30"}
{"Bash":"gresource extract /usr/lib/x86_64-linux-gnu/libadwaita-1.so.0 /org/gnome/Adwaita/styles/defaults-dark.css 2>/dev/null"}
{"Bash":"gresource extract /usr/lib/x86_64-linux-gnu/libadwaita-1.so.0 /org/gnome/Adwaita/styles/defaults-dark-yaru-default.css 2>/dev/null"}
{"Bash":"dpkg -l yaru-theme-gnome-shell libadwaita-1-0 2>/dev/null | awk '/^ii/{print $2, $3}'; strings /usr/lib/x86_64-linux-gnu/libadwaita-1.so.0 | grep -i 'yaru\|priority\|801\|820' | head -20"}
{"Bash":"gresource extract /usr/lib/x86_64-linux-gnu/libadwaita-1.so.0 /org/gnome/Adwaita/styles/base-yaru.css 2>/dev/null | head -40"}
{"Bash":"gsettings get com.ubuntu.desktop.interface color-scheme 2>/dev/null; gsettings get com.ubuntu.desktop.interface yaru-accent-color 2>/dev/null; gsettings list-keys com.ubuntu.desktop.interface 2>/dev/null | head -20"}
{"Bash":"gsettings list-schemas 2>/dev/null | grep -i ubuntu | head -10; gsettings get org.gnome.desktop.interface gtk-theme 2>/dev/null"}
{"Bash":"gsettings get org.gnome.desktop.interface gtk-theme 2>/dev/null; gsettings get org.gnome.desktop.interface color-scheme 2>/dev/null; gsettings list-schemas 2>/dev/null | grep -i 'yaru\|adw'"}
{"Bash":"gresource extract /usr/lib/x86_64-linux-gnu/libadwaita-1.so.0 /org/gnome/Adwaita/styles/base-yaru.css 2>/dev/null | grep -i 'accent'"}
{"Bash":"echo "GTK_THEME=$GTK_THEME"; echo "GTK_DEBUG=$GTK_DEBUG"; gsettings get org.gnome.desktop.interface gtk-theme; gsettings get org.gnome.desktop.interface color-scheme"}
